    const sharedDefaultTotal=activeDefaults.reduce((sum,entry)=>sum+entry.default_quantity,0);
    if(pack.franchise_mode==="shared"&&sharedDefaultTotal>sharedAllowance){toast(`Os padrões somam ${sharedDefaultTotal}, acima da franquia de ${sharedAllowance}. Ajuste a distribuição.`,true);return}
    if(pack.franchise_mode==="shared"&&sharedAllowance>0&&!activeDefaults.length){toast(`Defina um padrão maior que zero para pelo menos um componente de “${pack.name}”.`,true);return}
    if(pack.availability_rule==="one_available_with_priority_fallback"&&(activeDefaults.length!==1||activeDefaults[0].default_quantity!==1)){toast(`O grupo “${pack.name}” precisa ter uma opção padrão na quantidade 1.`,true);return}
    if(["single_required","decay"].includes(pack.kind)&&(activeDefaults.length!==1||activeDefaults[0].default_quantity!==1)){toast(`O grupo “${pack.name}” precisa ter exatamente uma escolha padrão.`,true);return}
    if(configs.length){const {error}=await db.from("item_component_config").upsert(configs,{onConflict:"item_id,package_id,composition_id"});if(error){toast(error.message,true);return}}
